let launchProducts=[],visibleLaunchProducts=[],selectedLaunchIndex=0;
const launchGrid=document.getElementById('launch-grid');
const groupNames={'biscuits':'Biscuits & Cookies','cookie-bite':'Cookie Bite','cookie-ball':'Cookie Ball','drink-powder':'Soft Drink Powder','tasty-saline':'Tasty Saline','tiffin':'Tiffin+','ener':'Ener-G'};
function showProduct(index, products=visibleLaunchProducts){selectedLaunchIndex=index;const product=products[index];content.replaceChildren();content.append(el('p',(product.company||'Grameen Danone').toUpperCase()+' / PRODUCT LAUNCH','eyebrow'),el('h2',product.name));content.lastChild.id='dialog-title';content.append(el('p',product.pack+' · '+groupNames[product.category],'role'));const stage=el('div',null,'product-detail-stage');const img=el('img');img.src=product.image;img.alt=product.name+' — '+product.pack+' packaging mockup';stage.append(img);content.append(stage);const controls=el('div',null,'product-controls');const prev=el('button','← Previous');const count=el('span',(index+1)+' / '+products.length);const next=el('button','Next →');prev.type=next.type='button';prev.disabled=index===0;next.disabled=index===products.length-1;prev.addEventListener('click',()=>showProduct(index-1,products));next.addEventListener('click',()=>showProduct(index+1,products));controls.append(prev,count,next);content.append(controls,el('p','Launched by Md. Nazmul Hasan during his '+(product.company||'Grameen Danone')+' role. Supplied product visual; original packaging and brand assets remain with their respective owners.','evidence-note'));dialog.scrollTop=0;if(!dialog.open){dialog.showModal();document.body.classList.add('modal-open');}}
function renderLaunchGallery(category){visibleLaunchProducts=launchProducts.filter(p=>category==='all'||p.category===category);mountProductSlider(launchGrid,visibleLaunchProducts,document.getElementById('gallery-status'));}
document.querySelectorAll('[data-launch-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-launch-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});renderLaunchGallery(button.dataset.launchFilter)}));
fetch('products.json').then(r=>{if(!r.ok)throw Error('Unavailable');return r.json()}).then(data=>{launchProducts=data;renderLaunchGallery('all')}).catch(()=>{document.getElementById('gallery-status').textContent='Product gallery could not load. Please refresh the page.'});
